(window.CARDS = window.CARDS || {}).series = [{"name":"Игра престолов","emoji":"🐉","meta":["драма, фэнтези","2011–2019","США"],"description":"Эпическая экранизация цикла романов Джорджа Мартина о войне знатных домов за Железный трон Вестероса. HBO объединили в сериале политические интриги, масштабные сражения и мифологию с драконами и угрозой из-за Стены. На пике популярности сериал собирал у экранов десятки миллионов зрителей по всему миру.","fact":"Финальный сезон вызвал волну петиций от разочарованных зрителей с требованием переснять концовку заново.","wiki_en":"Game of Thrones"},{"name":"Во все тяжкие","emoji":"🧪","meta":["драма, криминал","2008–2013","США"],"description":"История школьного учителя химии, который после диагноза «рак» начинает готовить метамфетамин, чтобы обеспечить семью, и постепенно превращается в безжалостного криминального авторитета. Сериал славится продуманной драматургией и постепенным перерождением главного героя.","fact":"Создатель сериала Винс Гиллиган описывал его идею как превращение мистера Чипса в Скарфейса.","wiki_en":"Breaking Bad"},{"name":"Друзья","emoji":"☕","meta":["ситком","1994–2004","США"],"description":"Ситком о шестерых друзьях, которые живут по соседству в Нью-Йорке и вместе проходят через работу, отношения и взросление. Львиная доля действия происходит в квартирах героев и кофейне Central Perk, ставшей одним из самых узнаваемых мест на телевидении.","fact":"Актёры настояли на равной оплате друг другу и в поздних сезонах получали по миллиону долларов за серию каждый.","wiki_en":"Friends"},{"name":"Офис","emoji":"📎","meta":["мокьюментари, комедия","2005–2013","США"],"description":"Американская адаптация британского ситкома в формате псевдодокументалистики о буднях сотрудников захолустной бумажной компании Dunder Mifflin. Съёмочная группа якобы снимает документальный фильм, а герои то и дело обращаются прямо в камеру.","fact":"Сериал начинался как почти дословный ремейк британского оригинала, но со второго сезона обрёл собственный тон и стал самостоятельным явлением.","wiki_en":"The Office (American TV series)"},{"name":"Симпсоны","emoji":"🍩","meta":["мультсериал, комедия","с 1989","США"],"description":"Мультсериал о жёлтолицей семье из вымышленного города Спрингфилд, который сатирически высмеивает американский быт, поп-культуру и политику. Идёт дольше любого другого прайм-таймового сериала в истории американского телевидения.","fact":"Многие сюжетные повороты «Симпсонов» позже неожиданно сбывались в реальности, что породило целый интернет-миф о его предсказаниях.","wiki_en":"The Simpsons"},{"name":"Южный Парк","emoji":"🏔️","meta":["мультсериал, комедия","с 1997","США"],"description":"Скандальный мультсериал о четырёх мальчишках из маленького горного городка в Колорадо, который высмеивает актуальные новости и общественные табу почти без фильтров. Эпизоды часто пишутся и монтируются буквально за несколько дней до эфира, чтобы успеть за повесткой.","fact":"Один из главных героев, Кенни, регулярно погибает в каждой серии ранних сезонов и неизменно возвращается целым и невредимым в следующей.","wiki_en":"South Park"},{"name":"Гриффины","emoji":"🐶","meta":["мультсериал, комедия","с 1999","США"],"description":"Мультсериал о нелепой семье Гриффин из вымышленного городка Куахог, где происходящее то и дело прерывается абсурдными отступлениями и пародийными флешбэками. Создатель Сет Макфарлейн озвучивает сразу нескольких ключевых персонажей, включая говорящего пса Брайана.","fact":"После отмены из-за низких рейтингов в начале 2000-х сериал был возвращён в эфир во многом благодаря бешеной популярности повторов и продаж DVD.","wiki_en":"Family Guy"},{"name":"Рик и Морти","emoji":"🌀","meta":["мультсериал, фантастика","с 2013","США"],"description":"Мультсериал о гениальном и циничном учёном-алкоголике Рике и его тревожном внуке Морти, которые путешествуют между бесчисленными измерениями и мирами. Под слоем безумного юмора и научной фантастики скрываются размышления о смысле существования и семейных отношениях.","fact":"Боевой клич Рика Wubba lubba dub dub его друг Птичья Персона переводит куда печальнее: «мне очень больно, пожалуйста, помогите».","wiki_en":"Rick and Morty"},{"name":"Футурама","emoji":"🚀","meta":["мультсериал, фантастика","с 1999, с перерывами","США"],"description":"Мультсериал от создателя «Симпсонов» Мэтта Грейнинга о курьере Фрае, который замерзает в криокапсуле в 1999 году и просыпается тысячу лет спустя в причудливом будущем. Вместе с экипажем звездолёта доставки он попадает в приключения по всей галактике.","fact":"Несмотря на несколько отмен и закрытий, сериал неоднократно возвращался благодаря фильмам, новым сезонам и стриминговым перезапускам.","wiki_en":"Futurama"},{"name":"Очень странные дела","emoji":"💡","meta":["фантастика, ужасы","с 2016","США"],"description":"Ностальгическая по восьмидесятым история о компании подростков из маленького городка Хокинс, где после исчезновения мальчика начинают происходить сверхъестественные события. Сериал переплетает подростковую дружбу с мифологией параллельного мира — Изнанки.","fact":"Сериал сделал звёздами почти неизвестных до него детей-актёров и заодно вернул на первый план Вайнону Райдер, звезду кино 1990-х.","wiki_en":"Stranger Things"},{"name":"Клан Сопрано","emoji":"🍝","meta":["драма, криминал","1999–2007","США"],"description":"Драма о боссе итало-американской мафии из Нью-Джерси, который параллельно с криминальными делами ходит на сеансы к психотерапевту, пытаясь справиться с паническими атаками. Сериал во многом задал стандарт для современной «престижной» телевизионной драмы.","fact":"Финальная сцена в закусочной, которая обрывается внезапным затемнением прямо под играющую песню, до сих пор остаётся предметом споров.","wiki_en":"The Sopranos"},{"name":"Прослушка","emoji":"🎧","meta":["драма, криминал","2002–2008","США"],"description":"Многослойная драма о Балтиморе, которая через прослушку телефонов наркоторговцев показывает город со всех сторон — от полиции и портовых докеров до школ, политиков и прессы. Каждый сезон переключает фокус на новый институт городской жизни.","fact":"Сериал не получил ни одной награды «Эмми» во время оригинального эфира, хотя критики регулярно называют его одним из лучших в истории телевидения.","wiki_en":"The Wire"},{"name":"Шерлок","emoji":"🔍","meta":["детектив, драма","2010–2017","Великобритания"],"description":"Современная британская интерпретация историй Артура Конан Дойля, где Шерлок Холмс и доктор Ватсон действуют в сегодняшнем Лондоне со смартфонами и соцсетями вместо телеграмм. Сериал известен стремительным темпом и визуализацией хода мыслей детектива прямо на экране.","fact":"Из-за плотных графиков актёров сериал выходит очень короткими сезонами по три полнометражных эпизода, а перерывы между сезонами растягивались на годы.","wiki_en":"Sherlock (TV series)"},{"name":"Доктор Хаус","emoji":"🩺","meta":["драма","2004–2012","США"],"description":"Медицинская драма о блестящем, но крайне неуживчивом диагносте докторе Хаусе, который вместе с командой врачей распутывает самые загадочные и редкие случаи болезней. Герой славится циничными репликами и правилом, что пациенты всегда лгут.","fact":"Образ Хауса создатели сериала прямо вдохновили детективом Шерлоком Холмсом, вплоть до адреса квартиры и верного друга-помощника.","wiki_en":"House (TV series)"},{"name":"Остаться в живых","emoji":"🏝️","meta":["драма, фантастика","2004–2010","США"],"description":"После крушения самолёта группа выживших пассажиров оказывается на таинственном тропическом острове, где происходят необъяснимые события. Сериал сочетает драму отношений между героями с мифологией острова, раскрывающейся через флешбэки.","fact":"Сериал одним из первых массово использовал нелинейные флешбэки и флешфорварды как основной инструмент повествования на телевидении.","wiki_en":"Lost (TV series)"},{"name":"Побег","emoji":"⛓️","meta":["драма, триллер","2005–2009","США"],"description":"Инженер Майкл Скофилд специально идёт на преступление, чтобы попасть в тюрьму, где несправедливо осуждён его брат, и вытатуировывает на теле план побега. Сериал построен вокруг напряжённой подготовки и исполнения дерзкого тюремного побега.","fact":"Огромную татуировку-карту актёру не набивали, а наносили гримёры переводными деталями — процедура занимала по несколько часов.","wiki_en":"Prison Break"},{"name":"Декстер","emoji":"🔪","meta":["драма, триллер","2006–2013","США"],"description":"Судебный эксперт по анализу крови Декстер Морган днём помогает полиции Майами раскрывать убийства, а по ночам сам убивает преступников, следуя строгому «кодексу» приёмного отца. Сериал держится на закадровых размышлениях героя о собственной двойной жизни.","fact":"Главную роль сыграл Майкл Си Холл, до этого известный по другому необычному сериалу о смерти — «Клиент всегда мёртв».","wiki_en":"Dexter (TV series)"},{"name":"Ходячие мертвецы","emoji":"🧟","meta":["ужасы, драма","2010–2022","США"],"description":"Экранизация комиксов о шерифе Рике Граймсе, который приходит в себя после комы в мире, захваченном зомби-эпидемией, и собирает вокруг себя группу выживших. По ходу сериала акцент смещается с самих зомби на противостояние разных человеческих группировок.","fact":"Долгое время сериал был самым популярным шоу на кабельном телевидении США среди зрителей до 49 лет.","wiki_en":"The Walking Dead (TV series)"},{"name":"Теория Большого взрыва","emoji":"🤓","meta":["ситком","2007–2019","США"],"description":"Ситком о компании учёных-физиков из Калтеха, чья жизнь строится вокруг науки, комиксов и видеоигр, пока в доме напротив не поселяется симпатичная официантка Пенни. Юмор строится на контрасте между гениальностью героев в науке и их неловкостью в обычном общении.","fact":"Формулы на досках в кадре для достоверности писал приглашённый консультант — физик из Калифорнийского университета.","wiki_en":"The Big Bang Theory"},{"name":"Как я встретил вашу маму","emoji":"☂️","meta":["ситком","2005–2014","США"],"description":"Тед Мосби из будущего рассказывает своим детям долгую и запутанную историю о том, как он познакомился с их мамой, попутно вспоминая годы дружбы, любви и приключений с четырьмя близкими друзьями в Нью-Йорке. Ключевую роль в компании играет эксцентричный обаятельный Барни.","fact":"Саму маму зрители впервые видят только к финалу восьмого сезона, а до этого о ней намекают деталями вроде жёлтого зонтика.","wiki_en":"How I Met Your Mother"},{"name":"Клиника","emoji":"🏥","meta":["ситком","2001–2010","США"],"description":"Комедийный сериал о буднях молодого врача Джей Ди в вымышленной больнице Сэйкред Харт, где абсурдный юмор соседствует с неожиданно серьёзными и трогательными медицинскими сюжетами. Значительная часть шуток строится на фантазиях главного героя, которые зритель видит прямо на экране.","fact":"Многие сюжеты сериала основаны на реальных историях, которые сценаристам рассказывал консультант-врач, работавший в настоящей больнице.","wiki_en":"Scrubs (TV series)"},{"name":"Секс в большом городе","emoji":"👠","meta":["комедия, драма","1998–2004","США"],"description":"Колумнистка Кэрри Брэдшоу и три её близкие подруги живут насыщенной жизнью в Нью-Йорке, обсуждая любовь, карьеру и секс за бокалом коктейлей «Космополитан». Каждая серия строится вокруг колонки, которую Кэрри пишет о современных отношениях.","fact":"Гардероб героинь, включая знаменитые туфли Маноло Бланик, сам по себе стал важной частью культурного наследия сериала.","wiki_en":"Sex and the City"},{"name":"Отчаянные домохозяйки","emoji":"🏡","meta":["драма, комедия","2004–2012","США"],"description":"Жизнь нескольких домохозяек на тихой улочке Вистерия-Лейн, полной секретов, измен и преступлений, показана глазами их соседки, покончившей с собой в первой серии и комментирующей события из-за кадра. Сериал сочетает мыльную оперу с чёрным юмором и детективной интригой.","fact":"Идея сериала пришла его создателю после того, как он посмотрел выпуск новостей о матери, которая утопила своих детей.","wiki_en":"Desperate Housewives"},{"name":"Сплетница","emoji":"💌","meta":["драма","2007–2012","США"],"description":"Жизнь избалованных подростков с Верхнего Ист-Сайда Манхэттена показана через анонимные сообщения таинственного блогера-сплетницы, который знает обо всех тайнах, изменах и скандалах привилегированной молодёжи. Каждый эпизод сопровождается её закадровыми репликами.","fact":"Закадровый голос Сплетницы принадлежит актрисе Кристен Белл, а личность самого автора блога раскрывают только в финальной серии.","wiki_en":"Gossip Girl"},{"name":"Анатомия страсти","emoji":"❤️‍🩹","meta":["драма","с 2005","США"],"description":"Медицинская драма о хирургах-ординаторах больницы Сиэтл Грейс, чья профессиональная жизнь неотделима от запутанных личных отношений и романов друг с другом. Сериал известен закадровыми монологами главной героини Мередит Грей и стал одним из самых долгоживущих драматических шоу США.","fact":"Название сериала обыгрывает старинный медицинский трактат по анатомии, которым пользовалось не одно поколение врачей.","wiki_en":"Grey's Anatomy"},{"name":"Секретные материалы","emoji":"👽","meta":["фантастика, детектив","1993–2018","США"],"description":"Агенты ФБР Малдер и Скалли расследуют дела, связанные с паранормальными явлениями, инопланетянами и правительственными заговорами, при этом герой верит в необъяснимое, а его напарница-скептик ищет рациональные объяснения. Сериал во многом определил жанр телевизионного мистического детектива девяностых.","fact":"Слоган сериала «Истина где-то рядом» стал крылатой фразой далеко за пределами телевидения.","wiki_en":"The X-Files"},{"name":"Твин Пикс","emoji":"🪵","meta":["детектив, мистика","1990–1991","США"],"description":"Расследование убийства школьницы Лоры Палмер приводит агента ФБР Дейла Купера в маленький городок Твин-Пикс, где за фасадом уютной провинции скрываются сюрреалистичные тайны и потусторонние силы. Сериал Дэвида Линча совместил детективный сюжет с атмосферой сновидения.","fact":"Знаменитая фраза «Совы не то, чем они кажутся» стала одним из главных символов загадочной мифологии сериала.","wiki_en":"Twin Peaks"},{"name":"Настоящий детектив","emoji":"🥃","meta":["детектив, драма","с 2014","США"],"description":"Антологический сериал, где каждый сезон рассказывает отдельную мрачную детективную историю с новыми героями и актёрами. Первый и самый известный сезон следит за двумя напарниками-детективами, которые на протяжении почти двадцати лет расследуют серию ритуальных убийств в Луизиане.","fact":"Шестиминутная сцена в четвёртом эпизоде первого сезона снята одним непрерывным кадром и стала одной из самых обсуждаемых на телевидении.","wiki_en":"True Detective"},{"name":"Чёрное зеркало","emoji":"📱","meta":["фантастика, драма","с 2011","Великобритания"],"description":"Антологический сериал, где почти каждая серия — самостоятельная мрачная притча о том, как современные технологии способны исказить человеческие отношения и общество. Название отсылает к тёмному экрану гаджета, в который мы вглядываемся, как в зеркало.","fact":"Один из эпизодов сериала был интерактивным фильмом «Брандашмыг», где зритель сам выбирал развитие сюжета.","wiki_en":"Black Mirror"},{"name":"Острые козырьки","emoji":"🎩","meta":["драма, криминал","2013–2022","Великобритания"],"description":"История бирмингемской криминальной семьи Шелби, которая после Первой мировой войны выстраивает собственную преступную империю под руководством харизматичного и расчётливого Томаса Шелби. Название отсылает к легенде, будто члены банды прятали бритвенные лезвия в козырьках кепок.","fact":"Хотя действие происходит в начале двадцатого века, саундтрек сериала почти целиком построен на современной рок- и электронной музыке.","wiki_en":"Peaky Blinders"},{"name":"Викинги","emoji":"⚔️","meta":["драма, история","2013–2020","Канада"],"description":"Полулегендарная история скандинавского вождя Рагнара Лодброка, который поднимает своих соплеменников на дерзкие морские походы в Западную Европу. Сериал вольно опирается на скандинавские саги и хроники, смешивая исторические события с мифологией.","fact":"Многие диалоги в сериале звучат на древнескандинавском и староанглийском языках с субтитрами для достоверности эпохи.","wiki_en":"Vikings (2013 TV series)"},{"name":"Ведьмак","emoji":"🐺","meta":["фэнтези, драма","с 2019","США"],"description":"Экранизация книжного цикла Анджея Сапковского о ведьмаке Геральте из Ривии — наёмном охотнике на чудовищ, чей путь переплетается с судьбами чародейки Йеннифэр и принцессы Цири. Сериал сочетает мрачное фэнтези с политическими интригами враждующих королевств.","fact":"Генри Кавилл — большой фанат книг и игр о ведьмаке, и для роли он снимался в белом парике и жёлтых контактных линзах.","wiki_en":"The Witcher (TV series)"},{"name":"Мандалорец","emoji":"🪖","meta":["фантастика","с 2019","США"],"description":"Одинокий охотник за головами в стальной броне из вселенной «Звёздных войн» берёт под защиту загадочного малыша своего вида и отправляется в опасное путешествие через окраины галактики. Сериал возродил дух вестерна на далёкой периферии знакомой саги.","fact":"Милого зелёного персонажа-малыша, которого фанаты прозвали «Бэби Йода», студия официально не называла по имени до второго сезона.","wiki_en":"The Mandalorian"},{"name":"Одни из нас","emoji":"🍄","meta":["драма, ужасы","с 2023","США"],"description":"Экранизация видеоигры о контрабандисте Джоэле, который берётся сопроводить через опустошённую грибковой пандемией Америку девочку-подростка Элли, возможно, хранящую ключ к спасению человечества. Сериал делает акцент на драме отношений героев не меньше, чем на выживании среди заражённых.","fact":"Сценарий сериала во многом писали создатели оригинальной игры, что позволило сохранить сюжет и характеры почти без изменений.","wiki_en":"The Last of Us (TV series)"},{"name":"Чернобыль","emoji":"☢️","meta":["драма, история","2019","США, Великобритания"],"description":"Минисериал о катастрофе на Чернобыльской атомной электростанции в 1986 году и её последствиях для ликвидаторов, учёных и жителей близлежащих городов. Создатели воссоздали советский быт и атмосферу эпохи с большим вниманием к деталям.","fact":"Для съёмок сериала многие интерьеры и улицы воссоздавали в Литве, где сохранилась советская архитектура похожего стиля.","wiki_en":"Chernobyl (miniseries)"},{"name":"Корона","emoji":"👑","meta":["драма, история","2016–2023","Великобритания"],"description":"Драма прослеживает жизнь британской королевы Елизаветы Второй и её семьи от восшествия на престол в начале пятидесятых до недавних десятилетий, показывая закулисье монархии на фоне больших исторических событий. Через несколько сезонов основной актёрский состав полностью меняется, чтобы соответствовать возрасту героев.","fact":"Ради исторической достоверности создатели воссоздавали костюмы и интерьеры по архивным фотографиям и подлинным королевским нарядам.","wiki_en":"The Crown (TV series)"},{"name":"Бумажный дом","emoji":"🎭","meta":["драма, криминал","2017–2021","Испания"],"description":"Группа грабителей под руководством загадочного Профессора устраивает дерзкий захват Королевского монетного двора Испании, чтобы напечатать миллиарды евро изнутри, а не украсть их. Все участники банды берут себе имена городов, а маски в стиле Сальвадора Дали стали визитной карточкой сериала.","fact":"Испанский сериал стал одним из самых просматриваемых неанглоязычных проектов Netflix во всём мире.","wiki_en":"Money Heist"},{"name":"Игра в кальмара","emoji":"🦑","meta":["драма, триллер","2021","Южная Корея"],"description":"Сотни людей, погрязших в долгах, соглашаются участвовать в серии смертельно опасных детских игр ради огромного денежного приза. За соревнованием тайно наблюдают богатые зрители, для которых чужое отчаяние превращается в развлечение.","fact":"Сериал стал самым просматриваемым проектом за всю историю Netflix на момент выхода.","wiki_en":"Squid Game"},{"name":"Нарко","emoji":"🌿","meta":["драма, криминал","2015–2017","США"],"description":"Сериал реконструирует историю противостояния колумбийских наркокартелей и правительственных агентов США, в центре которой — восхождение и падение печально известного наркобарона Пабло Эскобара. Повествование сочетает документальные архивные кадры с драматизированными сценами.","fact":"Часть сериала снималась непосредственно в Колумбии, а некоторые локации связаны с реальными событиями из жизни картеля.","wiki_en":"Narcos"},{"name":"Озарк","emoji":"💵","meta":["драма, криминал","2017–2022","США"],"description":"Финансовый консультант Марти Бёрд вынужден с семьёй переехать в курортный регион Озарк, чтобы отмывать деньги для мексиканского наркокартеля и расплатиться с долгами. Сериал показывает, как благополучная с виду семья постепенно погружается в криминальный мир.","fact":"Название отсылает к реальному региону Озарк на стыке Миссури и Арканзаса, где по сюжету и разворачивается почти всё действие.","wiki_en":"Ozark (TV series)"},{"name":"Лучше звоните Солу","emoji":"⚖️","meta":["драма, криминал","2015–2022","США"],"description":"Приквел «Во все тяжкие» рассказывает историю адвоката Джимми Макгилла, который постепенно превращается в изворотливого юриста-мошенника Сола Гудмана. Сериал детально показывает моральное падение героя задолго до событий основного шоу.","fact":"Многие критики называют этот приквел равным или даже превосходящим по драматургии оригинальный сериал «Во все тяжкие».","wiki_en":"Better Call Saul"},{"name":"Безумцы","emoji":"🥃","meta":["драма","2007–2015","США"],"description":"Драма о сотрудниках рекламного агентства на Мэдисон-авеню в Нью-Йорке начала шестидесятых, в центре которой — харизматичный, но закрытый креативный директор Дон Дрейпер. Сериал славится дотошным воссозданием моды, интерьеров и нравов той эпохи.","fact":"По утверждению создателей, Mad Men — сленговое прозвище, которым рекламщики с Мэдисон-авеню называли сами себя.","wiki_en":"Mad Men"},{"name":"Карточный домик","emoji":"🃏","meta":["драма","2013–2018","США"],"description":"Циничный конгрессмен Фрэнк Андервуд, обойдённый обещанным назначением, начинает беспощадную интригу по восхождению к вершинам американской власти, время от времени обращаясь напрямую к зрителю. Сериал стал одним из первых крупных оригинальных проектов Netflix.","fact":"Американская версия — ремейк британского мини-сериала 1990 года, снятого по роману Майкла Доббса.","wiki_en":"House of Cards (American TV series)"},{"name":"Наследники","emoji":"💼","meta":["драма, чёрная комедия","2018–2023","США"],"description":"Сатирическая драма о медиамагнате Логане Рое и его взрослых детях, которые плетут интриги и грызутся между собой за право унаследовать его глобальную медиаимперию. Сериал беспощадно высмеивает нравы сверхбогатых и корпоративную борьбу за власть.","fact":"Сценарий во многом вдохновлён реальными медиадинастиями, хотя создатели всегда подчёркивали, что персонажи вымышлены.","wiki_en":"Succession (TV series)"},{"name":"Белый лотос","emoji":"🌺","meta":["чёрная комедия, драма","с 2021","США"],"description":"Антологический сериал, каждый сезон которого разворачивается в новом роскошном отеле сети «Белый лотос» и следит за постояльцами и персоналом, чьи скрытые пороки и конфликты постепенно выходят наружу. С первых минут сезона зрителю известно, что кто-то из героев погибнет.","fact":"Первый сезон снимали на Гавайях в настоящем курортном отеле, где во время съёмок жила и вся съёмочная группа.","wiki_en":"The White Lotus"},{"name":"Эйфория","emoji":"💊","meta":["драма","с 2019","США"],"description":"Сериал показывает жизнь группы американских старшеклассников через призму зависимостей, поиска идентичности и первой любви, часто прибегая к ярким визуальным приёмам и закадровым монологам героини Ру. Тема наркозависимости раскрывается без прикрас и смягчения.","fact":"Яркий макияж с блёстками, который носят героини сериала, спровоцировал отдельный модный тренд, получивший собственное название.","wiki_en":"Euphoria (American TV series)"},{"name":"Уэнздей","emoji":"🖤","meta":["комедия, ужасы","с 2022","США"],"description":"Дочь семейки Аддамс Уэнздей поступает в мрачную академию для изгоев Невермор, где ей приходится раскрывать сверхъестественную тайну, заводить первых в жизни друзей и разбираться с собственными паранормальными способностями. Сериал сочетает готическую эстетику с подростковой комедией.","fact":"Танец, который героиня исполняет на школьном балу, был во многом придуман самой актрисой и стал вирусным в соцсетях по всему миру.","wiki_en":"Wednesday (TV series)"},{"name":"Бриджертоны","emoji":"💍","meta":["драма, романтика","с 2020","США"],"description":"Экранизация романов Джулии Куин о большом семействе Бриджертонов в лондонском высшем свете эпохи Регентства, где каждый сезон в центре внимания оказывается любовная история одного из братьев или сестёр. За скандалами и слухами светского общества незримо следит анонимная сплетница леди Уислдаун.","fact":"В сериале, в отличие от классических костюмных драм, актёрский состав подчёркнуто мультирасовый, что стало предметом широкого обсуждения.","wiki_en":"Bridgerton"},{"name":"Ход королевы","emoji":"♟️","meta":["драма","2020","США"],"description":"Минисериал о юной шахматной вундеркинде Бет Хармон, которая растёт в приюте, борется с зависимостью от успокоительных и постепенно пробивается к вершинам мужского по большей части шахматного мира. Сериал показывает шахматные партии почти так же напряжённо, как спортивные поединки.","fact":"После выхода сериала во всём мире резко вырос интерес к шахматам, включая продажи шахматных досок и записи на уроки игры.","wiki_en":"The Queen's Gambit (miniseries)"},{"name":"Тед Лассо","emoji":"⚽","meta":["комедия, спорт","2020–2023","США"],"description":"Американский тренер по американскому футболу без всякого опыта в европейском футболе неожиданно возглавляет английский клуб и покоряет скептически настроенную команду неизменным оптимизмом и добротой. Сериал прославился тёплым, почти терапевтическим тоном в противовес циничным комедиям.","fact":"Персонаж Теда Лассо впервые появился ещё в рекламных роликах канала NBC про английскую Премьер-лигу за несколько лет до сериала.","wiki_en":"Ted Lasso"},{"name":"Медведь","emoji":"🐻","meta":["драма, комедия","с 2022","США"],"description":"Молодой шеф-повар высокой кухни возвращается в родной Чикаго, чтобы взять на себя семейную закусочную после смерти брата, и пытается навести порядок среди хаоса кухни и собственных травм. Сериал известен напряжёнными, почти документальными сценами работы ресторанной кухни.","fact":"Один из самых обсуждаемых эпизодов сделан так, будто снят одним непрерывным кадром, — это до предела усиливает ощущение кухонного хаоса.","wiki_en":"The Bear (TV series)"},{"name":"Разделение","emoji":"🧠","meta":["фантастика, триллер","с 2022","США"],"description":"Сотрудники загадочной корпорации проходят процедуру «разделения», которая буквально раскалывает их сознание на рабочую и повседневную личности, не помнящие друг о друге. Сериал строит напряжённую антиутопию вокруг вопросов идентичности и контроля корпорации над жизнью человека.","fact":"Внешние виды и холл корпорации снимали в реальном модернистском здании бывших исследовательских лабораторий в Нью-Джерси.","wiki_en":"Severance (TV series)"},{"name":"Пацаны","emoji":"🦸","meta":["фантастика, чёрная комедия","с 2019","США"],"description":"В мире, где супергерои — это продукт корпорации, зарабатывающей на их культе, группа обычных людей мстит продажным и жестоким «героям» за причинённый ими вред. Сериал беспощадно пародирует супергеройский жанр и высмеивает индустрию медиа-культов.","fact":"Многие персонажи сериала — узнаваемые пародии на культовых супергероев из комиксов известных издательств.","wiki_en":"The Boys (TV series)"},{"name":"Дом Дракона","emoji":"🐲","meta":["фэнтези, драма","с 2022","США"],"description":"Приквел «Игры престолов» разворачивается почти за двести лет до событий основного сериала и рассказывает о кровавой междоусобной войне за престол внутри дома Таргариенов, известной как «Танец драконов». Драконов здесь заметно больше, чем в основном сериале, и у каждого свой наездник из Таргариенов.","fact":"Основой сериала стала книга Джорджа Мартина «Пламя и кровь», написанная как псевдоисторическая хроника династии Таргариенов.","wiki_en":"House of the Dragon"},{"name":"Локи","emoji":"⚡","meta":["фантастика","с 2021","США"],"description":"После событий фильмов о Мстителях бог обмана Локи попадает в загадочное Управление Временными Изменениями, которое следит за целостностью временной линии, и вынужден сотрудничать с его агентами. Сериал стал первым в киновселенной Marvel, всерьёз затронувшим тему мультивселенной.","fact":"Локи Том Хиддлстон играет с самого первого «Тора» 2011 года — это одна из самых долгих ролей в киновселенной Marvel.","wiki_en":"Loki (TV series)"},{"name":"Аркейн","emoji":"💜","meta":["мультсериал, фэнтези","2021–2024","США"],"description":"Анимационный сериал по мотивам вселенной игры League of Legends рассказывает о двух сёстрах из разделённых на богатый и нищий кварталы города Пилтовера и Зауна, чьи пути расходятся из-за трагедии детства. Известен необычным, почти живописным стилем анимации.","fact":"Сериал делали около шести лет, и он стал одной из самых дорогих и технически сложных анимационных постановок своего времени.","wiki_en":"Arcane (TV series)"},{"name":"Аватар: Легенда об Аанге","emoji":"🌊","meta":["мультсериал, фэнтези","2005–2008","США"],"description":"Мультсериал о мире, разделённом на четыре народа, каждый из которых способен управлять одной из стихий, и о юном Аватаре Аанге, который должен овладеть всеми четырьмя стихиями и остановить войну Народа Огня. Сочетает восточную эстетику с проработанным взрослым сюжетом.","fact":"Создатели сериала консультировались с мастерами боевых искусств, чтобы каждый стиль владения стихией был основан на реальной технике.","wiki_en":"Avatar: The Last Airbender"},{"name":"Губка Боб Квадратные Штаны","emoji":"🧽","meta":["мультсериал, комедия","с 1999","США"],"description":"Мультсериал о неунывающей жёлтой морской губке в квадратных штанах, которая живёт в подводном городе Бикини Боттом, работает поваром в закусочной «Красти Краб» и постоянно попадает в нелепые ситуации вместе с друзьями. Стал одним из самых узнаваемых мультипликационных брендов в мире.","fact":"Создатель сериала Стивен Хилленбург до мультипликации работал морским биологом, что заметно повлияло на подводный сеттинг шоу.","wiki_en":"SpongeBob SquarePants"},{"name":"Наруто","emoji":"🍥","meta":["аниме","2002–2007","Япония"],"description":"Аниме о юном ниндзя Наруто Удзумаки, который мечтает стать самым сильным лидером своей деревни, несмотря на то что внутри него запечатан могучий демонический дух лисицы. Сериал прослеживает взросление героя, его дружбу и соперничество с товарищами по команде.","fact":"«Наруто» — это ещё и название спиральных ломтиков рыбного паштета для рамэна, а рамэн в сериале — любимая еда героя.","wiki_en":"Naruto"},{"name":"Ван-Пис","emoji":"🏴‍☠️","meta":["аниме","с 1999","Япония"],"description":"Аниме о молодом пирате Монки Д. Луффи, который благодаря случайно съеденному дьявольскому фрукту обрёл резиновое тело и вместе с командой отправился на поиски легендарного сокровища Ван-Пис. Один из самых продолжительных и коммерчески успешных аниме-сериалов в истории.","fact":"Манга-первоисточник сериала официально признана самой продаваемой серией комиксов одного автора в истории.","wiki_en":"One Piece"},{"name":"Атака титанов","emoji":"🗡️","meta":["аниме","2013–2023","Япония"],"description":"Человечество укрылось за гигантскими стенами от человекоподобных великанов-титанов, пожирающих людей, пока однажды стена не рушится под ударом Титана-Колосса. Сериал постепенно раскрывает сложную политическую и историческую подоплёку конфликта людей и титанов.","fact":"По словам автора манги Хадзимэ Исаямы, замысел родился отчасти из его опыта работы в интернет-кафе и общения с непредсказуемыми посетителями.","wiki_en":"Attack on Titan"},{"name":"Тетрадь смерти","emoji":"📓","meta":["аниме","2006–2007","Япония"],"description":"Старшеклассник Лайт Ягами находит тетрадь смерти, способную убить любого, чьё имя в неё вписано, и решает с её помощью очистить мир от преступников, превращаясь в загадочного вершителя правосудия по прозвищу Кира. Против него начинает расследование гениальный детектив L.","fact":"Правила использования тетради смерти настолько детально продуманы, что фанаты годами разбирают их логические лазейки и противоречия.","wiki_en":"Death Note"},{"name":"Покемон","emoji":"⚡","meta":["аниме","с 1997","Япония"],"description":"Аниме о юном тренере Эше Кетчуме и его электрическом покемоне Пикачу, которые путешествуют по разным регионам, ловят и тренируют других покемонов и участвуют в турнирах, чтобы стать чемпионами. Основано на культовой серии видеоигр и породило одну из крупнейших медиафраншиз в мире.","fact":"Один из эпизодов 1997 года вызвал у японских зрителей приступы из-за часто мигающих кадров и после этого никогда больше не выходил в эфир.","wiki_en":"Pokémon (TV series)"},{"name":"Сейлор Мун","emoji":"🌙","meta":["аниме","1992–1997","Япония"],"description":"Обычная японская школьница Усаги Цукино превращается в воительницу в матроске Сейлор Мун и вместе с другими девушками-воительницами защищает Землю от тёмных сил. Один из первых по-настоящему массово популярных аниме о волшебницах-воительницах за пределами Японии.","fact":"Сериал сыграл ключевую роль в популяризации жанра махо-сёдзё и аниме в целом среди западной аудитории в девяностые годы.","wiki_en":"Sailor Moon (TV series)"},{"name":"Мистер Бин","emoji":"🧸","meta":["комедия","1990–1995","Великобритания"],"description":"Комедийный сериал почти без диалогов о нелепом и эксцентричном англичанине мистере Бине, чьи простейшие бытовые ситуации неизменно превращаются в цепочку абсурдных недоразумений. Физический, визуальный юмор сделал шоу понятным зрителям независимо от языка.","fact":"Из-за минимального количества реплик сериал легко экспортировался по всему миру почти без адаптации и озвучки.","wiki_en":"Mr. Bean"},{"name":"Доктор Кто","emoji":"📞","meta":["фантастика","с 1963","Великобритания"],"description":"Многолетний британский сериал о путешествующем во времени и пространстве инопланетянине Докторе, который летает на машине времени в виде синей полицейской будки и периодически «перерождается» в новое тело. Один из самых долгоживущих научно-фантастических сериалов на телевидении.","fact":"Способность Доктора «перерождаться» изначально придумали как сюжетный ход, чтобы заменить исполнителя главной роли без остановки сериала.","wiki_en":"Doctor Who"},{"name":"Зачарованные","emoji":"🔮","meta":["фэнтези, драма","1998–2006","США"],"description":"Три сестры Холливелл узнают, что они потомки могущественного рода ведьм, и должны использовать унаследованную магию, чтобы защищать невинных от демонов и тёмных сил. Сериал сочетает семейную драму с еженедельными магическими сражениями.","fact":"Сериал стал одним из самых долгоживущих телешоу с главными героинями-женщинами в жанре фэнтези на американском телевидении.","wiki_en":"Charmed"},{"name":"Спасатели Малибу","emoji":"🏖️","meta":["драма, экшн","1989–2001","США"],"description":"Сериал о буднях спасателей на пляжах Малибу, которые не только вытаскивают из воды тонущих отдыхающих, но и распутывают личные драмы и криминальные истории. В девяностые считался одним из самых просматриваемых телесериалов в мире.","fact":"На пике популярности сериал, по разным оценкам, еженедельно смотрело более миллиарда зрителей по всему миру.","wiki_en":"Baywatch"},{"name":"Альф","emoji":"👽","meta":["комедия","1986–1990","США"],"description":"После крушения инопланетного корабля на Земле пушистое существо по имени Альф поселяется в доме обычной американской семьи, скрываясь от властей и то и дело устраивая бытовой хаос. Персонаж Альфа — кукла-аниматроник, управляемая кукловодом из-под пола.","fact":"Из-за кукольной механики Альфа редко показывали в полный рост, а декорации приподняли над полом, чтобы под ними работали кукловоды.","wiki_en":"ALF (TV series)"},{"name":"Санта-Барбара","emoji":"🌴","meta":["мыльная опера","1984–1993","США"],"description":"Многолетняя американская мыльная опера о жизни, любви и интригах нескольких богатых семей калифорнийского города Санта-Барбара. В постсоветских странах сериал стал одним из первых массово популярных иностранных телесериалов девяностых.","fact":"Сериал выходил почти десять лет и насчитывает больше двух тысяч эпизодов — по одному почти на каждый рабочий день.","wiki_en":"Santa Barbara (TV series)"},{"name":"Менталист","emoji":"🎯","meta":["детектив, драма","2008–2015","США"],"description":"Бывший фальшивый экстрасенс Патрик Джейн помогает калифорнийскому бюро расследований раскрывать преступления, используя не сверхспособности, а острую наблюдательность и знание психологии. Параллельно герой ведёт личную охоту на серийного убийцу, погубившего его семью.","fact":"Прототипом главного героя во многом послужили реальные менталисты и «холодные чтецы», которые создают иллюзию чтения мыслей без всякой мистики.","wiki_en":"The Mentalist"},{"name":"Форс-мажоры","emoji":"👔","meta":["драма","2011–2019","США"],"description":"Талантливый молодой человек без диплома юриста устраивается на работу в престижную нью-йоркскую юридическую фирму благодаря невероятной памяти и хитрости, скрывая от коллег и клиентов обман. Сериал сочетает юридическую драму с историей дружбы и наставничества.","fact":"Оригинальное английское название Suits обыгрывает и деловые костюмы юристов, и судебные иски, которые ведут герои.","wiki_en":"Suits (American TV series)"},{"name":"Люцифер","emoji":"😈","meta":["фэнтези, детектив","2016–2021","США"],"description":"Дьявол устаёт от вечного правления Адом и переезжает в Лос-Анджелес, где открывает ночной клуб и по совместительству помогает полиции раскрывать убийства благодаря способности заставлять людей признаваться в своих желаниях. Сериал основан на персонаже комиксов издательства Vertigo.","fact":"Персонаж Люцифера впервые появился ещё в комиксах «Песочный человек» Нила Геймана до того, как получил собственную серию комиксов и сериал.","wiki_en":"Lucifer (TV series)"},{"name":"Сверхъестественное","emoji":"🔥","meta":["фэнтези, ужасы","2005–2020","США"],"description":"Братья Сэм и Дин Винчестеры колесят по Америке на старом «Шевроле Импала», охотясь на демонов, призраков и прочую нечисть, попутно оказываясь в центре противостояния Рая и Ада. Один из самых долгоживущих сериалов в жанре фэнтези-ужасов на американском телевидении.","fact":"Чёрный «Шевроле Импала» 1967 года, на котором ездят герои, стал таким же узнаваемым символом сериала, как и сами братья.","wiki_en":"Supernatural (American TV series)"},{"name":"Дневники вампира","emoji":"🧛","meta":["фэнтези, драма","2009–2017","США"],"description":"Старшеклассница Елена Гилберт влюбляется в благородного вампира Стефана Сальваторе, но вскоре в её жизни появляется его непредсказуемый брат Дэймон, и оба брата оказываются втянуты в вечное соперничество за её сердце. Действие происходит в маленьком городке Мистик-Фоллс, полном сверхъестественных существ.","fact":"Съёмки сериала проходили в реальном городке Ковингтон в штате Джорджия, который стал популярным местом паломничества фанатов.","wiki_en":"The Vampire Diaries"},{"name":"Мир Дикого Запада","emoji":"🤖","meta":["фантастика, драма","2016–2022","США"],"description":"Огромный тематический парк развлечений населён человекоподобными андроидами, которые изо дня в день разыгрывают сюжеты вестерна для богатых посетителей, пока в их программах не начинают проступать признаки настоящего сознания. Сериал поднимает вопросы о природе сознания и свободы воли.","fact":"Сериал основан на одноимённом фантастическом фильме 1973 года, который был одним из первых голливудских фильмов с компьютерной анимацией.","wiki_en":"Westworld (TV series)"},{"name":"Фарго","emoji":"❄️","meta":["чёрная комедия, криминал","с 2014","США"],"description":"Антологический сериал по мотивам одноимённого фильма братьев Коэн, каждый сезон которого рассказывает отдельную историю о нелепых и кровавых преступлениях среди заснеженных пейзажей американского Среднего Запада. Сериал сохраняет фирменную коэновскую смесь чёрного юмора и внезапного насилия.","fact":"Несмотря на антологический формат с новыми героями каждый сезон, некоторые сюжетные детали едва заметно связывают все сезоны между собой.","wiki_en":"Fargo (TV series)"},{"name":"Мистер Робот","emoji":"💻","meta":["драма, триллер","2015–2019","США"],"description":"Талантливый, но психически нестабильный программист-хакер по ночам вступает в подпольную группу анархистов, которая планирует уничтожить долговые записи крупнейшей корпорации мира. Сериал известен точным изображением реального хакерства и нестандартной операторской работой.","fact":"Создатель сериала Сэм Эсмейл увлекался программированием с юности и держал на площадке консультантов по кибербезопасности ради достоверности сцен взлома.","wiki_en":"Mr. Robot"},{"name":"Бруклин 9-9","emoji":"👮","meta":["ситком","2013–2021","США"],"description":"Комедийный сериал о буднях эксцентричных детективов нью-йоркского полицейского участка Бруклин 9-9 во главе со строгим, но справедливым капитаном Рэймондом Холтом. Сочетает полицейские расследования с непрекращающимися розыгрышами и дружескими подколками между напарниками.","fact":"Капитан Холт в сериале — один из первых открыто гомосексуальных чернокожих героев в главной роли комедийного сериала на американском телевидении.","wiki_en":"Brooklyn Nine-Nine"},{"name":"Сайнфелд","emoji":"🥨","meta":["ситком","1989–1998","США"],"description":"Ситком о нью-йоркском комике Джерри Сайнфелде и трёх его чудаковатых друзьях, чьи серии часто строятся вокруг совершенно бытовых мелочей и абсурдных мелких конфликтов. Сам сериал шутливо называли «шоу ни о чём» за отсутствие сквозных сюжетных линий.","fact":"Финал 1998 года собрал у экранов десятки миллионов американцев и стал одним из самых массово просмотренных финалов в истории телевидения.","wiki_en":"Seinfeld"},{"name":"Бригада","emoji":"🔫","meta":["драма, криминал","2002","Россия"],"description":"Сериал о четырёх друзьях детства, которые в постсоветской Москве девяностых постепенно превращаются из обычных парней в лидеров крупной криминальной группировки. Прослеживает восхождение и неизбежное падение банды на фоне бурной эпохи девяностых.","fact":"Актёр Сергей Безруков, сыгравший главаря банды Сашу Белого, после выхода сериала долгие годы ассоциировался у зрителей именно с этой ролью.","wiki_en":"Brigada"},{"name":"Семнадцать мгновений весны","emoji":"🕵️","meta":["драма, шпионский","1973","СССР"],"description":"Советский разведчик Максим Исаев, работающий под именем штандартенфюрера Штирлица в структурах нацистской Германии, пытается предотвратить сепаратные переговоры немцев с западными союзниками в последние месяцы войны. Один из самых культовых советских телесериалов.","fact":"Фразы и сцены из сериала настолько прочно вошли в культуру, что породили целый жанр анекдотов про Штирлица.","wiki_en":"Seventeen Moments of Spring"},{"name":"Место встречи изменить нельзя","emoji":"🚔","meta":["детектив, драма","1979","СССР"],"description":"Экранизация романа братьев Вайнеров о работе московского уголовного розыска в первые послевоенные годы, где опытный сыщик Глеб Жеглов и молодой Владимир Шарапов расходятся во взглядах на методы борьбы с преступностью. Сериал считается одним из лучших советских детективов.","fact":"Роль Глеба Жеглова, сыгранная Владимиром Высоцким, стала одной из последних крупных работ актёра перед смертью.","wiki_en":"The Meeting Place Cannot Be Changed"},{"name":"Ликвидация","emoji":"🕶️","meta":["детектив, драма","2007","Россия, Украина"],"description":"Действие детективного сериала разворачивается в послевоенной Одессе 1946 года, где сотрудники уголовного розыска пытаются справиться с разгулом бандитизма во главе с загадочным преступным авторитетом по кличке Академик. Сериал воссоздаёт колоритную атмосферу и говор послевоенной Одессы.","fact":"Одесский диалект и характерные выражения героев сериала быстро разошлись на цитаты далеко за пределами города.","wiki_en":"Liquidation (TV series)","wiki_ru":"Ликвидация (телесериал)"},{"name":"Улицы разбитых фонарей","emoji":"🌃","meta":["детектив","с 1997","Россия"],"description":"Один из первых и самых долгоживущих российских детективных сериалов о буднях оперативников петербургского уголовного розыска, которые в каждой серии расследуют новое преступление. Сериал породил целую волну похожих отечественных детективных франшиз.","fact":"Основой сериала стали книги Андрея Кивинова, который сам служил в петербургском уголовном розыске.","wiki_en":"Streets of Broken Lights"},{"name":"Интерны","emoji":"🩺","meta":["ситком","2010–2016","Россия"],"description":"Комедийный сериал о буднях молодых врачей-интернов московской больницы под руководством едкого и требовательного доктора Быкова. Формат во многом ориентирован на популярные американские медицинские ситкомы, адаптированные под российские реалии.","fact":"Главную роль едкого доктора Быкова сыграл Иван Охлобыстин, до сериала известный скорее как актёр авторского кино и сценарист.","wiki_en":"Interny (TV series)","wiki_ru":"Интерны"},{"name":"Кухня","emoji":"🍳","meta":["ситком","2012–2016","Россия"],"description":"Ситком о поварах и персонале дорогого ресторана, где талантливый, но неопытный молодой повар пытается пробиться под руководством вспыльчивого и требовательного шеф-повара. Сериал породил несколько полнометражных продолжений и спин-оффов.","fact":"Вспыльчивого шеф-повара Виктора Баринова сыграл Дмитрий Назаров, и именно этот образ стал самым узнаваемым в сериале.","wiki_en":"Kitchen (Russian TV series)","wiki_ru":"Кухня (телесериал)"},{"name":"Универ","emoji":"🎓","meta":["ситком","2007–2011","Россия"],"description":"Молодёжный ситком о жизни студентов, живущих в общежитии одного из московских университетов, снятый в формате многокамерного ситкома со зрительским смехом за кадром. Сериал стал одним из самых заметных проектов российского молодёжного телевидения двухтысячных.","fact":"У сериала появилось продолжение — «Универ. Новая общага», где действие в той же общаге продолжилось уже с новыми героями.","wiki_en":"Univer (TV series)","wiki_ru":"Универ (телесериал)"},{"name":"Физрук","emoji":"🏋️","meta":["ситком","2014–2018","Россия"],"description":"Бывший криминальный авторитет по прозвищу Фома после выхода из тюрьмы устраивается на работу учителем физкультуры в обычную школу, принося в размеренную школьную жизнь свои криминальные повадки и специфическое чувство юмора. Главную роль сыграл актёр Дмитрий Нагиев.","fact":"В школу Фома идёт вовсе не по призванию — ему нужно подобраться поближе к дочери своего бывшего шефа.","wiki_en":"Fizruk"},{"name":"Сваты","emoji":"🍷","meta":["комедия","2008–2019","Украина, Россия"],"description":"Комедийный сериал о двух семьях свойственников с разным достатком и взглядами на жизнь, чьи дети поженились, а сами родители вынуждены то и дело общаться и мириться с характерами друг друга. Действие в основном происходит в деревенском доме одной из семей.","fact":"Сериал снимался на Украине, а его актёрский состав объединил известных актёров сразу из нескольких постсоветских стран.","wiki_en":"Svaty (TV series)","wiki_ru":"Сваты"},{"name":"Папины дочки","emoji":"👧","meta":["ситком","2007–2013","Россия"],"description":"Ситком о папе-психологе, который после ухода жены в одиночку воспитывает пятерых очень разных по характеру дочерей и с трудом справляется с их выходками. Снят в формате многокамерного ситкома со зрительским смехом за кадром.","fact":"Спустя годы после финала сериал получил продолжение, где выросшие героини вернулись уже вместе с новым поколением детей.","wiki_en":"Daddy's Daughters"},{"name":"Моя прекрасная няня","emoji":"🧹","meta":["ситком","2004–2009","Россия"],"description":"Ситком о простодушной, но обаятельной провинциальной девушке, которая неожиданно становится няней в доме богатого столичного продюсера и постепенно покоряет сердца всей его семьи. Сериал — российская адаптация американского ситкома «Няня».","fact":"Героиня приехала в Москву из Мариуполя, и её яркий говор с характерными интонациями стал визитной карточкой сериала.","wiki_en":"My Fair Nanny","wiki_ru":"Моя прекрасная няня"},{"name":"Не родись красивой","emoji":"👓","meta":["мелодрама","2005–2006","Россия"],"description":"Мелодрама о скромной и не слишком привлекательной по меркам глянца девушке, которая устраивается на работу в модный дом и вопреки насмешкам коллег постепенно добивается успеха и любви. Сериал — российская адаптация популярного латиноамериканского телеформата об утёнке, покоряющем мир моды.","fact":"Оригинальный формат сериала, колумбийская теленовелла, был адаптирован на телевидении десятков стран мира, и российская версия стала одной из самых успешных.","wiki_en":"Not Born Beautiful","wiki_ru":"Не родись красивой"},{"name":"Слово пацана. Кровь на асфальте","emoji":"🥊","meta":["драма, криминал","2023","Россия"],"description":"Драма о подростковых уличных группировках в Казани конца восьмидесятых годов, где мальчишки из разных дворов живут по жёстким неписаным законам улицы. Сериал вызвал широкое общественное обсуждение подростковой преступности после выхода.","fact":"После премьеры сериала в нескольких российских регионах прошли специальные обсуждения и профилактические меры из-за опасений подражания героям среди подростков.","wiki_en":"The Boy's Word: Blood on the Asphalt"},{"name":"Эпидемия","emoji":"❄️","meta":["драма, триллер","2019–2022","Россия"],"description":"После вспышки смертельного вируса в России группа случайных попутчиков пытается на машине добраться сквозь опустевшую и погружённую в хаос страну до безопасного укрытия на удалённом озере. Сериал снят по мотивам романа Яны Вагнер «Вонгозеро».","fact":"Российская премьера прошла незадолго до начала пандемии COVID-19, а на Netflix сериал вышел под названием To the Lake.","wiki_en":"To the Lake"},{"name":"Мажор","emoji":"🚓","meta":["драма, криминал","2014–2019","Россия"],"description":"Избалованный сын высокопоставленного чиновника после серьёзного проступка отправляется отцом служить рядовым оперативником в московскую полицию, где ему приходится с нуля заслуживать уважение коллег. Сериал сочетает детективные сюжеты с историей взросления избалованного героя.","fact":"После телевизионных сезонов историю героя продолжили в полнометражном фильме, вышедшем уже в кинопрокат.","wiki_en":"Mazhor","wiki_ru":"Мажор (телесериал)"},{"name":"Метод","emoji":"🔦","meta":["детектив, триллер","2015–2018","Россия"],"description":"Эксцентричный следователь с неординарными, почти пугающими методами расследования берёт в напарницы молодую сотрудницу полиции, чтобы вместе охотиться на маньяков и серийных убийц. Сериал известен мрачной атмосферой и нестандартной операторской работой.","fact":"Главную роль сыграл актёр Константин Хабенский, а сериал сравнивали по стилистике с зарубежными триллерами о серийных убийцах.","wiki_en":"The Method (TV series)"},{"name":"Полицейский с Рублёвки","emoji":"🚨","meta":["комедия","2016–2019","Россия"],"description":"Простоватый участковый переводится служить в элитный посёлок для сверхбогатых на Рублёвке, где ему приходится разбираться с капризами и странностями обеспеченных жителей, оставаясь в душе честным и бесхитростным человеком. Сериал сочетает полицейские сюжеты с комедией нравов.","fact":"У сериала вышло полнометражное продолжение «Полицейский с Рублёвки. Новогодний беспредел», ставшее хитом российского кинопроката.","wiki_en":"A Cop from Rublyovka","wiki_ru":"Полицейский с Рублёвки"},{"name":"Ну, погоди!","emoji":"🐺","meta":["мультфильм","с 1969","СССР"],"description":"Советский мультсериал о нескладном, но упрямом Волке, который на протяжении множества коротких серий безуспешно пытается поймать весёлого и находчивого Зайца. Почти лишённый диалогов сериал построен на выразительной пантомиме и музыкальных номерах.","fact":"Реплику «Ну, заяц, погоди!», произносимую Волком почти в каждой серии, зрители запомнили настолько, что она дала название всему мультсериалу.","wiki_en":"Well, Just You Wait!"},{"name":"Смешарики","emoji":"🐰","meta":["мультсериал","с 2004","Россия"],"description":"Российский мультсериал о круглых забавных существах-шариках, которые живут в вымышленном лесном мире и через простые бытовые истории знакомят маленьких зрителей с основами дружбы, науки и взаимопомощи. Сериал экспортировался и адаптировался для показа во многих странах мира.","fact":"За рубежом сериал выходил под другими названиями, включая версии GoGoRiki и KikoRiki для разных международных рынков.","wiki_en":"Smeshariki"},{"name":"Маша и Медведь","emoji":"🐻","meta":["мультсериал","с 2009","Россия"],"description":"Мультсериал о неугомонной маленькой девочке Маше, которая своими бесконечными шалостями постоянно испытывает терпение приютившего её доброго, но уставшего от её энергии медведя. Один из самых успешных российских анимационных проектов, завоевавших популярность далеко за пределами страны.","fact":"Эпизод «Маша плюс каша» набрал на YouTube миллиарды просмотров и стал одним из самых просматриваемых видео в истории сервиса.","wiki_en":"Masha and the Bear"}];
